module.exports = /*#__PURE__*/JSON.parse('[{"id":"proj-1790194386351","slug":"the-magic-box","title":"THE MAGIC BOX","category":"AI Video & Film","type":"Cinematic Trailer / Commercial","client":"ANIMATION STUDIO FANTASY","role":"AI Creator & Developer","year":"2026","featured":true,"videoUrl":"https://www.youtube.com/watch?v=fbaUGbX4Ij8","thumbnailUrl":"https://img.youtube.com/vi/fbaUGbX4Ij8/hqdefault.jpg","bannerUrl":"https://img.youtube.com/vi/fbaUGbX4Ij8/maxresdefault.jpg","summary":"THE MAGIC BOX | A Fun & Magical 3D Animated Short Film","description":"THE MAGIC BOX is a playful 3D animated short film filled with magic, comedy, surprises, and adventure. What begins as an innocent discovery quickly turns into a hilarious chain of unexpected events when the magic inside the box refuses to behave as planned.\\n\\n🎬 Genre: 3D Animation / Comedy / Fantasy\\n🎥 Format: AI Animated Short Film\\n✨ Style: Colorful, Playful, Cinematic\\n🎭 Themes: Curiosity • Imagination • Magic • Comedy • Adventure\\n\\nOne mysterious box. Endless possibilities. And one very curious character.\\n\\nWatch until the end to see what happens when the magic gets completely out of control!\\n\\nIf you enjoyed the animation, LIKE, COMMENT, and SUBSCRIBE for more AI-generated animated stories, cinematic short films, fantasy adventures, and creative visual projects.","technicalBreakdown":{"overview":"THE MAGIC BOX | A Fun & Magical 3D Animated Short Film","pipeline":["3D Concept Art & Character Design","AI Generative Video Animation & Motion Physics","Magical Particle VFX & Lighting Rendering","Voice Synthesis, Foley Sound Effects & Orchestral Scoring"],"aiToolsUsed":["Midjourney v6","Runway Gen-3","Luma Dream Machine","ElevenLabs","Topaz 4K AI"],"techStack":["Diffusion Video Latents","Consistent Character Seeds","Spatial Foley Audio"],"keyChallenges":["Maintaining playful character expressions and lighting consistency across high-energy magical transformations."],"outcomes":["Complete 3D animated cinematic short","Vibrant colorful aesthetic with 4K clarity","Engaging narrative pacing with comedic timing"]},"metrics":[{"label":"Quality","value":"4K UHD"},{"label":"Scenes","value":"5+ Scenes"},{"label":"Animation Style","value":"3D Cinematic"},{"label":"Sound Design","value":"Full Spatial"}]},{"id":"proj-1790194214580","slug":"the-last-human","title":"THE LAST HUMAN","category":"AI Video & Film","type":"Cinematic Trailer / Commercial","client":"MOVIE DIRECTOR","role":"AI Creator & Developer","year":"2026","featured":true,"videoUrl":"https://www.youtube.com/watch?v=kOeXjZ-aNmc","thumbnailUrl":"https://img.youtube.com/vi/kOeXjZ-aNmc/hqdefault.jpg","bannerUrl":"https://img.youtube.com/vi/kOeXjZ-aNmc/maxresdefault.jpg","summary":"THE LAST HUMAN | A Cinematic Sci-Fi Mystery Short Film","description":"After awakening inside an abandoned underground facility, Elias discovers a terrifying message: he may be the last human alive. As he explores the empty laboratories, strange movements and unexplained signals lead him deeper into the facility.\\n\\nThen he discovers something impossible.\\n\\nA chamber filled with mysterious human pods.\\nA figure who looks exactly like him.\\nAnd a truth that could change everything he thought he knew about humanity.\\n\\nTHE LAST HUMAN is a cinematic sci-fi mystery thriller exploring isolation, identity, artificial evolution, and the frightening possibility that humanity was never destroyed — it was replaced.\\n\\n🎬 Genre: Sci-Fi / Mystery / Thriller\\n🎥 Format: AI Cinematic Short Film\\n🌌 Style: Dark, Cinematic, Suspenseful, Futuristic\\n⏱️ Duration: 60–90 Seconds\\n\\nOne survivor. One impossible discovery. One final question:\\n\\nIf humanity no longer needed you… would you still belong?","technicalBreakdown":{"overview":"THE LAST HUMAN | A Cinematic Sci-Fi Mystery Short Film","pipeline":["Sci-Fi Underground Environment Worldbuilding","Character Consistency & Facial Seed Locking","Atmospheric Volumetric Lighting & Suspense Pacing","Custom Voiceover Synthesis & Dystopian Sound Design"],"aiToolsUsed":["Midjourney v6","Runway Gen-3","ElevenLabs","DaVinci Resolve"],"techStack":["Generative Sci-Fi Prompts","Multi-Angle Camera Renders","Neural Audio Mastering"],"keyChallenges":["Crafting dark, futuristic underground laboratory lighting with photorealistic reflections on sci-fi pods."],"outcomes":["Cinematic sci-fi mystery short film trailer","Pervasive suspenseful atmosphere and crisp visual storytelling","Immersive sound design"]},"metrics":[{"label":"Quality","value":"4K UHD"},{"label":"Scenes","value":"5+ Scenes"},{"label":"Atmosphere","value":"Suspense Sci-Fi"},{"label":"Render Style","value":"Photorealistic"}]},{"id":"proj-1790193412007","slug":"the-carpenters-son","title":"THE CARPENTER\'S SON","category":"AI Video & Film","type":"Cinematic Trailer / Commercial","client":"MOVIE TRAILER","role":"AI Creator & Developer","year":"2026","featured":true,"videoUrl":"https://www.youtube.com/watch?v=aVA4IPRQ9zg","thumbnailUrl":"https://img.youtube.com/vi/aVA4IPRQ9zg/hqdefault.jpg","bannerUrl":"https://img.youtube.com/vi/aVA4IPRQ9zg/maxresdefault.jpg","summary":"THE CARPENTER\'S SON | A Cinematic Biblical Short Film","description":"In a quiet town of ancient Judea, a young carpenter begins to realize that his life may be part of a story far greater than himself.\\n\\nTHE CARPENTER\'S SON is a cinematic biblical short film inspired by themes of faith, destiny, sacrifice, hope, and the extraordinary purpose hidden within an ordinary life.\\n\\nThrough atmospheric historical environments, dramatic cinematography, emotional performances, and powerful storytelling, the film recreates the world of ancient Judea and follows a mysterious journey that will change everything.\\n\\n🎬 Genre: Biblical / Historical Drama / Mystery\\n🎥 Format: AI Cinematic Short Film\\n🏺 Setting: Ancient Judea\\n✨ Themes: Faith • Destiny • Sacrifice • Hope • Purpose","technicalBreakdown":{"overview":"THE CARPENTER\'S SON | A Cinematic Biblical Short Film","pipeline":["Historical Judean Era Research & Prompt Engineering","Ancient Texture & Lighting Calibration","Dramatic Narrative Trajectory & Scene Blocking","Orchestral Score & Foley Sound Integration"],"aiToolsUsed":["Midjourney v6","Runway Gen-3","Luma Dream Machine","Topaz Video AI"],"techStack":["Historical Style Diffusion","Character Consistency","Dynamic Camera Panning"],"keyChallenges":["Accurate historical architecture and garment consistency across changing daylight conditions."],"outcomes":["Deeply atmospheric biblical drama trailer","Rich historical fidelity and emotional storytelling"]},"metrics":[{"label":"Quality","value":"4K UHD"},{"label":"Scenes","value":"7+ Scenes"},{"label":"Era Setting","value":"Ancient Judea"},{"label":"Soundtrack","value":"Orchestral"}]},{"id":"proj-1790192309058","slug":"family-issues","title":"FAMILY ISSUES","category":"AI Video & Film","type":"Cinematic Trailer / Commercial","client":"MOVIE DIRECTOR","role":"AI Creator & Developer","year":"2026","featured":true,"videoUrl":"https://www.youtube.com/watch?v=rwHdlLc1Cp0","thumbnailUrl":"https://img.youtube.com/vi/rwHdlLc1Cp0/hqdefault.jpg","bannerUrl":"https://img.youtube.com/vi/rwHdlLc1Cp0/maxresdefault.jpg","summary":"FAMILY ISSUES | A Powerful Emotional Short Film","description":"Family can be the source of our greatest love — and sometimes our deepest pain.\\n\\nFAMILY ISSUES is an emotional short film exploring conflict, misunderstanding, broken relationships, and the difficult choices that can divide the people closest to us. Through a cinematic story filled with tension and emotion, the film shows how unresolved problems can affect an entire family — and why forgiveness, communication, and understanding can matter more than pride.\\n\\n🎬 Genre: Family Drama / Emotional\\n🎥 Format: AI Cinematic Short Film\\n💭 Themes: Family, Conflict, Love, Forgiveness, Relationships","technicalBreakdown":{"overview":"FAMILY ISSUES | A Powerful Emotional Short Film","pipeline":["Emotional Character Drama Scriptwriting","Intimate Close-Up Facial Expression Prompting","Dramatic Pacing & Scene Transition Editing","Nuanced Dialogue Synthesis & Foley Audio"],"aiToolsUsed":["Midjourney v6","Runway Gen-3","ElevenLabs","DaVinci Resolve"],"techStack":["Emotional Lighting Diffusion","Voice Emotion Tuning","Color Grading"],"keyChallenges":["Capturing subtle human facial micro-expressions of grief, conflict, and reconciliation."],"outcomes":["Compelling, emotionally resonant drama short film","High-fidelity human character animations"]},"metrics":[{"label":"Quality","value":"4K UHD"},{"label":"Scenes","value":"5+ Scenes"},{"label":"Genre","value":"Drama"},{"label":"Pacing","value":"Emotional"}]},{"id":"proj-1790191155011","slug":"the-lost-star","title":"THE LOST STAR","category":"AI Video & Film","type":"Cinematic Trailer / Commercial","client":"CHILDREN ANIMATION FANTASY","role":"AI Video Creator & Editor","year":"2026","featured":true,"videoUrl":"https://www.youtube.com/watch?v=b3uSmv06SkE","thumbnailUrl":"https://img.youtube.com/vi/b3uSmv06SkE/hqdefault.jpg","bannerUrl":"https://img.youtube.com/vi/b3uSmv06SkE/maxresdefault.jpg","summary":"THE LOST STAR | A Cinematic Fantasy Adventure Short Film","description":"A cinematic AI-generated fantasy short film titled “The Lost Star,” featuring an adventurous journey through an enchanted fantasy world of mystical forests, snow-covered mountains, magical landscapes, ancient villages, and dramatic cinematic environments.\\n\\nI developed the visual concept and storytelling direction, creating detailed AI prompts for characters, environments, atmospheric scenes, cinematic compositions, lighting, camera movement, and fantasy worldbuilding. The project combines AI video generation, image-to-video workflows, character direction, environment creation, cinematic framing, and visual storytelling to create a visually immersive fantasy experience.","technicalBreakdown":{"overview":"Cinematic AI-generated fantasy short film with mystical environments","pipeline":["Fantasy Worldbuilding & Biome Concept Art","Camera Motion & Fly-through Video Generation","Mystical Atmospheric Lighting & Glow Effects","Orchestral Score & Ambient Nature Audio Layering"],"aiToolsUsed":["Midjourney v6","Runway Gen-3","Luma Dream Machine","Topaz Video AI"],"techStack":["Fantasy Environment Prompts","Particle VFX","Atmospheric Volumetrics"],"keyChallenges":["Generating vast, seamless fantasy landscapes from mystical forests to snow-covered peaks with consistent art direction."],"outcomes":["Visually stunning fantasy trailer","Expansive worldbuilding and cinematic camera choreography"]},"metrics":[{"label":"Quality","value":"4K UHD"},{"label":"Scenes","value":"6+ Scenes"},{"label":"Worldbuilding","value":"Fantasy Realms"},{"label":"VFX","value":"Magical Glows"}]}]');

